<?php
declare(strict_types=1);require __DIR__.'/../../account-app/bootstrap.php';$admin=requireSuperAdmin();$message='';
if(($_SERVER['REQUEST_METHOD']??'GET')==='POST'){requireAccountCsrf();$allowed=['yankees','palworld','wishlist','ravens'];$update=db()->prepare('UPDATE site_visibility SET is_visible=?,updated_by=? WHERE site_key=?');foreach($allowed as $key)$update->execute([isset($_POST['visible'][$key])?1:0,$admin['id'],$key]);db()->prepare("INSERT INTO admin_audit_log(admin_user_id,action,target_type,details) VALUES (?,'visibility_updated','site',?)")->execute([$admin['id'],json_encode($_POST['visible']??[])]);$message='Homepage visibility updated.';}
$sites=db()->query('SELECT site_key,display_name,is_visible FROM site_visibility ORDER BY display_name')->fetchAll();renderAccountHeader('Site Visibility');?>
<section class="card"><h1>Site Visibility</h1><p class="muted">Hidden sites remain available by direct URL but do not appear on the KRYP12 homepage.</p><?php if($message):?><p class="success"><?=h($message)?></p><?php endif?><form method="post"><input type="hidden" name="csrf_token" value="<?=h(accountCsrf())?>"><?php foreach($sites as $site):?><label class="check-row"><span><strong><?=h($site['display_name'])?></strong><br><small class="muted">/<?=h($site['site_key'])?>/</small></span><input type="checkbox" name="visible[<?=h($site['site_key'])?>]" value="1" <?=$site['is_visible']?'checked':''?>></label><?php endforeach?><p><button>Save visibility</button></p></form></section>
<?php renderAccountFooter();
